  }

  initialize() {
    const jaegerExporter = new JaegerExporter({
      endpoint:
        process.env.JAEGER_ENDPOINT || "http://localhost:14268/api/traces",
    });

    const resource = Resource.default().merge(
      new Resource({
        [SemanticResourceAttributes.SERVICE_NAME]: this.serviceName,
        [SemanticResourceAttributes.SERVICE_VERSION]:
          process.env.SERVICE_VERSION || "1.0.0",
        [SemanticResourceAttributes.DEPLOYMENT_ENVIRONMENT]:
          process.env.NODE_ENV || "development",
      }),
    );

    this.sdk = new NodeSDK({
      resource,
      spanProcessor: new BatchSpanProcessor(jaegerExporter),
      instrumentations: [
        getNodeAutoInstrumentations({
          "@opentelemetry/instrumentation-fs": {
            enabled: false, // Too noisy
          },
          "@opentelemetry/instrumentation-http": {
            requestHook: (span, request) => {
              span.setAttribute(
                "http.request.body",
                JSON.stringify(request.body),
              );
            },
            responseHook: (span, response) => {
              span.setAttribute("http.response.size", response.length);
            },
          },
          "@opentelemetry/instrumentation-express": {
            requestHook: (span, req) => {
              span.setAttribute("user.id", req.user?.id);
              span.setAttribute("session.id", req.session?.id);
            },
          },
        }),
      ],
    });

    this.sdk.start();

    // Graceful shutdown
    process.on("SIGTERM", () => {
      this.sdk
        .shutdown()
        .then(() => console.log("Tracing terminated"))
        .catch((error) => console.error("Error terminating tracing", error))
        .finally(() => process.exit(0));
    });
  }

  // Custom span creation
  createSpan(name, fn, attributes = {}) {
    const tracer = trace.getTracer(this.serviceName);
    return tracer.startActiveSpan(name, async (span) => {
      try {
        // Add custom attributes
        Object.entries(attributes).forEach(([key, value]) => {
          span.setAttribute(key, value);
        });

        // Execute function
        const result = await fn(span);

        span.setStatus({ code: SpanStatusCode.OK });
        return result;
      } catch (error) {
        span.recordException(error);
        span.setStatus({
          code: SpanStatusCode.ERROR,
          message: error.message,
        });
        throw error;
      } finally {
        span.end();
      }
    });
  }
}

// Distributed tracing middleware
class TracingMiddleware {
  constructor() {
    this.tracer = trace.getTracer("http-middleware");
  }

  express() {
    return (req, res, next) => {
      const span = this.tracer.startSpan(`${req.method} ${req.path}`, {
        kind: SpanKind.SERVER,
        attributes: {
          "http.method": req.method,
          "http.url": req.url,
          "http.target": req.path,
          "http.host": req.hostname,
          "http.scheme": req.protocol,
          "http.user_agent": req.get("user-agent"),
          "http.request_content_length": req.get("content-length"),
        },
      });

      // Inject trace context into request
      req.span = span;
      req.traceId = span.spanContext().traceId;

      // Add trace ID to response headers
      res.setHeader("X-Trace-Id", req.traceId);

      // Override res.end to capture response data
      const originalEnd = res.end;
      res.end = function (...args) {
        span.setAttribute("http.status_code", res.statusCode);
        span.setAttribute(
          "http.response_content_length",
          res.get("content-length"),
        );

        if (res.statusCode >= 400) {
          span.setStatus({
            code: SpanStatusCode.ERROR,
            message: `HTTP ${res.statusCode}`,
          });
        }

        span.end();
        originalEnd.apply(res, args);
      };

      next();
    };
  }
}
