// sentry-setup.js
import * as Sentry from "@sentry/node";
import { ProfilingIntegration } from "@sentry/profiling-node";

class SentryErrorTracker {
  constructor(config) {
    this.config = config;
    this.initialized = false;
  }

  initialize() {
    Sentry.init({
      dsn: this.config.dsn,
      environment: this.config.environment,
      release: this.config.release,

      // Performance Monitoring
      tracesSampleRate: this.config.tracesSampleRate || 0.1,
      profilesSampleRate: this.config.profilesSampleRate || 0.1,

      // Integrations
      integrations: [
        // HTTP integration
        new Sentry.Integrations.Http({ tracing: true }),

        // Express integration
        new Sentry.Integrations.Express({
          app: this.config.app,
          router: true,
          methods: ["GET", "POST", "PUT", "DELETE", "PATCH"],
        }),

        // Database integration
        new Sentry.Integrations.Postgres(),
        new Sentry.Integrations.Mysql(),
        new Sentry.Integrations.Mongo(),

        // Profiling
        new ProfilingIntegration(),

        // Custom integrations
        ...this.getCustomIntegrations(),
      ],

      // Filtering
      beforeSend: (event, hint) => {
        // Filter sensitive data
        if (event.request?.cookies) {
          delete event.request.cookies;
        }

        // Filter out specific errors
        if (this.shouldFilterError(event, hint)) {
          return null;
        }

        // Enhance error context
        return this.enhanceErrorEvent(event, hint);
      },

      // Breadcrumbs
      beforeBreadcrumb: (breadcrumb, hint) => {
        // Filter sensitive breadcrumbs
        if (breadcrumb.category === "console" && breadcrumb.level === "debug") {
          return null;
        }

        return breadcrumb;
      },

      // Options
      attachStacktrace: true,
      shutdownTimeout: 5000,
      maxBreadcrumbs: 100,
      debug: this.config.debug || false,

      // Tags
      initialScope: {
        tags: {
          component: this.config.component,
          version: this.config.version,
        },
        user: {
          id: this.config.userId,
          segment: this.config.userSegment,
        },
      },
    });

    this.initialized = true;
    this.setupErrorHandlers();
  }

  setupErrorHandlers() {
    // Global error handler
    process.on("uncaughtException", (error) => {
      console.error("Uncaught Exception:", error);
      Sentry.captureException(error, {
        tags: { type: "uncaught_exception" },
        level: "fatal",
      });

      // Graceful shutdown
      this.gracefulShutdown();
    });

    // Promise rejection handler
    process.on("unhandledRejection", (reason, promise) => {
      console.error("Unhandled Rejection:", reason);
      Sentry.captureException(reason, {
        tags: { type: "unhandled_rejection" },
        extra: { promise: promise.toString() },
      });
    });
  }

  enhanceErrorEvent(event, hint) {
    // Add custom context
    event.extra = {
      ...event.extra,
      memory: process.memoryUsage(),
      uptime: process.uptime(),
      nodeVersion: process.version,
    };

    // Add user context
    if (this.config.getUserContext) {
      event.user = this.config.getUserContext();
    }

    // Add custom fingerprinting
    if (hint.originalException) {
      event.fingerprint = this.generateFingerprint(hint.originalException);
    }

    return event;
  }

  generateFingerprint(error) {
    // Custom fingerprinting logic
    const fingerprint = [];

    // Group by error type
    fingerprint.push(error.name || "Error");

    // Group by error location
    if (error.stack) {
      const match = error.stack.match(/at\s+(.+?)\s+\(/);
      if (match) {
        fingerprint.push(match[1]);
      }
    }

    // Group by custom properties
    if (error.code) {
      fingerprint.push(error.code);
    }

    return fingerprint;
  }
}

// Express middleware
export const sentryMiddleware = {
  requestHandler: Sentry.Handlers.requestHandler(),
  tracingHandler: Sentry.Handlers.tracingHandler(),
  errorHandler: Sentry.Handlers.errorHandler({
    shouldHandleError(error) {
      // Capture 4xx and 5xx errors
      if (error.status >= 400) {
        return true;
      }
      return false;
    },
  }),
};
