    def _calculate_slo_performance(self, service, month):
        """Calculate SLO performance metrics"""
        slos = {}

        # Availability SLO
        availability_query = f"""
        avg_over_time(
            service:success_rate_5m{{service="{service}"}}[{month}]
        )
